<?php
require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO customer_dates(customer_id,label,event_date,recipient,notes)VALUES(?,?,?,?,?)")->execute([$_POST['customer_id'],$_POST['label'],$_POST['event_date'],trim($_POST['recipient']),trim($_POST['notes'])]);audit('create','customer_dates',(int)$p->lastInsertId());go('crm.php');}
$customers=$p->query("SELECT id,name FROM customers ORDER BY name")->fetchAll();$rows=$p->query("SELECT cd.*,c.name customer,c.whatsapp FROM customer_dates cd JOIN customers c ON c.id=cd.customer_id ORDER BY substr(cd.event_date,6,5)")->fetchAll();page_head('CRM / Datas especiais');?>
<div class="grid g2"><div class="card"><h2>Nova data especial</h2><form method="post"><?=csrf_field()?><label>Cliente</label><select name="customer_id"><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><div class="grid g2"><div><label>Ocasião</label><input name="label" placeholder="Aniversário de casamento" required></div><div><label>Data</label><input type="date" name="event_date" required></div><div><label>Presenteado</label><input name="recipient" placeholder="Esposa, mãe..."></div></div><label>Observações</label><textarea name="notes"></textarea><button class="primary">Salvar data</button></form></div>
<div class="card"><h2>Uso comercial</h2><p>Essas datas permitem contatar o cliente antes do evento e oferecer novamente buquês, cestas e presentes.</p></div></div>
<div class="card"><div class="table"><table><tr><th>Cliente</th><th>WhatsApp</th><th>Ocasião</th><th>Data</th><th>Presenteado</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?></td><td><?=e($r['whatsapp'])?></td><td><?=e($r['label'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['recipient'])?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>